<?php
namespace App\Domain\GhostEvents\Services; use App\Domain\GhostEvents\Models\{GhostEvent,GhostEventAttempt}; use App\Domain\Races\Models\RaceRun; use App\Domain\Races\Models\RaceSession; use App\Domain\Races\Services\{RaceSessionService,RaceSubmissionService}; use App\Models\User; use App\Support\ApiException; use Illuminate\Support\Facades\DB;
class GhostEventService { public function __construct(private readonly RaceSessionService $sessions,private readonly RaceSubmissionService $submissions,private readonly GhostEventBundleService $bundles){} public function list(){return GhostEvent::where('enabled',true)->where('starts_at','<=',now())->where('ends_at','>',now())->get();} public function findBySlug(string $slug):GhostEvent{return GhostEvent::where('slug',$slug)->firstOr(fn()=>throw ApiException::notFound('Ghost event not found.'));} public function buildBundle(GhostEvent $event):array{return $this->bundles->build($event);} public function createSession(User $u,GhostEvent $e,bool $practice=false,?string $ip=null):RaceSession{if(!$practice&&(!$e->enabled||$e->starts_at->isFuture()||$e->ends_at->isPast()))throw ApiException::conflict('Ghost event is not active.');return $this->sessions->create($u,['courseId'=>$e->course_id,'weatherPresetId'=>$e->weather_preset_id,'physicsVersion'=>$e->physics_version,'contextType'=>'ghost_event','contextId'=>$e->id,'mode'=>$practice?'practice':'ranked','contextMetadata'=>['ghost_event_id'=>$e->id]],$ip);} public function submitAttempt(User $u,GhostEvent $e,array $p):GhostEventAttempt{return DB::transaction(function()use($u,$e,$p){$sid=(string)$p['submissionId'];if($a=GhostEventAttempt::where(['ghost_event_id'=>$e->id,'submission_id'=>$sid])->first())return $a;$s=$this->sessions->findOwned($u,(string)$p['sessionId']);if($s->context_type!=='ghost_event'||(int)$s->context_id!==$e->id)throw ApiException::forbidden('Session is not for this ghost event.');$practice=$s->mode==='practice';if(!$practice&&$e->max_attempts!==null&&GhostEventAttempt::where(['ghost_event_id'=>$e->id,'user_id'=>$u->id,'is_practice'=>false])->count()>=$e->max_attempts)throw ApiException::conflict('Ghost event attempt limit reached.');$run=$this->submissions->submit($u,$p);return GhostEventAttempt::create(['ghost_event_id'=>$e->id,'user_id'=>$u->id,'race_run_id'=>$run->id,'submission_id'=>$sid,'race_session_id'=>$s->id,'status'=>$run->status,'is_practice'=>$practice]);});} public function recordAccepted(RaceRun $run):void{if($run->context_type!=='ghost_event'||!$run->isAccepted())return;DB::transaction(function()use($run){$a=GhostEventAttempt::where('race_run_id',$run->id)->lockForUpdate()->first();if(!$a)return;$best=$a->event->benchmarks()->whereNotNull('duration_ms')->min('duration_ms');$beat=$best!==null&&$run->duration_ms<$best;$points=$beat?(int)(($a->event->reward_configuration_json??[])['season_points']??0):0;$a->update(['status'=>'accepted','duration_ms'=>$run->duration_ms,'benchmark_beaten'=>$beat,'delta_ms'=>$best===null?null:$run->duration_ms-$best,'accepted_at'=>$run->verified_at??now(),'season_points_awarded'=>$points]);GhostEventAttempt::where('ghost_event_id',$a->ghost_event_id)->where('status','accepted')->where('is_practice',false)->orderBy('duration_ms')->orderBy('accepted_at')->orderBy('id')->get()->each(fn($x,$i)=>$x->update(['rank'=>$i+1]));});} }
